#include "stm32f4xx.h"
#include <stdint.h>

uint8_t estado_actual = 0;

void init_GPIOA(void);


int main(void)
{
    init_GPIOA();
    /* Loop forever */
	while(1) {
        
    }
}


void init_GPIOA(void) {

//Lo primero a hacer es habilitar el reloj contador con el bus correspondiente al puerto que vamos a usar, en este caso,
//el puerto B va con el bus AHB1

//En el documento de referencia del stm32f411 (datasheet) buscamos cómo habilitar el bus AHB1 (pág. 117)

//Como queremos habilitar el puerto B, debemos poner un 1 en la posición donde esté según el datasheet, en este caso, debemos correr un 1 una vez (shift), porque siempre empieza en 1 con el puerto A
//Así que hacemos 1<<1

    RCC->AHB1ENR &= ~RCC_AHB1ENR_GPIOBEN; //Limpiamos el bit correspondiente al puerto B
    RCC->AHB1ENR |= RCC_AHB1ENR_GPIOBEN;

//Luego buscamos el GPIO register, y allí buscamos "GPIO port mode register"
//En dicho apartado, buscamos activar los pines necesarios, en este caso, los pines 6, 8 y 9, en modo de propósito general (general purpose output mode), que según el datasheet, es 01, así que debemos poner un 1 en la posición correspondiente a cada pin, y un 0 en la otra posición, por lo que debemos hacer un shift de 2 veces para cada pin

//VERDE (PUERTO 8)
    GPIOB->MODER &= ~(GPIO_MODER_MODE8_0); //Limpiamos el bit correspondiente al pin 8
    GPIOB->MODER |= GPIO_MODER_MODE8_0;

//El modo push-pull da una estado de 1 y 0, lo que brinda una corriente, mientras que el modo open-drain solo da un estado de 0.
//En el apartado de OTYPER (8.4.2) se activa el modo push-pull, que es el que queremos, y según el datasheet, debemos poner un 0 en la posición correspondiente a cada pin, por lo que no necesitamos hacer un shift

    GPIOB->OTYPER &= ~GPIO_OTYPER_OT8; //CONFIGURAMOS EL PB8 COMO SALIDA (PUSH PULL) (¿POR QUÉ?)

//Luego vamos a OSPEEDR (8.4.3) y buscamos la velocidad de los pines, en este caso, queremos que sea baja, por lo que debemos poner un 0 en la posición correspondiente a cada pin, por lo que no necesitamos hacer un shift

    GPIOB->OSPEEDR &= ~(GPIO_OSPEEDR_OSPEED8);

    GPIOB->PUPDR &= ~(GPIO_PUPDR_PUPD8);
    GPIOB->ODR &= ~(GPIO_ODR_OD8); //Iinicializar PB8 en bajo

//AMARILLO (PUERTO 9)

    GPIOB->MODER &= ~(GPIO_MODER_MODE9_0);
    GPIOB->MODER |= GPIO_MODER_MODE9_0;
    GPIOB->OTYPER &= ~GPIO_OTYPER_OT9;
    GPIOB->OSPEEDR &= ~ (GPIO_OSPEEDR_OSPEED9);
    GPIOB->PUPDR &= ~(GPIO_PUPDR_PUPD9);
    GPIOB->ODR &= ~(GPIO_ODR_OD9); //Iinicializar PB9 en bajo

//ROJO (PUERTO 6)

    GPIOB->MODER &= ~(GPIO_MODER_MODE6_0);
    GPIOB->MODER |= GPIO_MODER_MODE6_0;
    GPIOB->OTYPER &= ~GPIO_OTYPER_OT6;
    GPIOB->OSPEEDR &= ~ (GPIO_OSPEEDR_OSPEED6);
    GPIOB->PUPDR &= ~(GPIO_PUPDR_PUPD6);
    GPIOB->ODR &= ~(GPIO_ODR_OD6); //Iinicializar PB6 en bajo  

//Vamos a usar un contador que no es de ARM sino de STM, y se llama SYSTICK, en el documento STM32 cortex-M4. es de 24 bits y solo funciona en conteo descendente
//Solo habilitamos ENABLE, thickint no porque se usa para trabajar con interrupciones. (4.5.1)
    
//Luego vamos a 4.5.2 y ajustamos el tiempo que queremos que dure el contador, en este caso, queremos que dure 1 segundo, por lo que debemos poner un 1 en la posición correspondiente a cada pin
    SysTick->LOAD = 16000000 -1; //Cargamos el valor de 1 segundo (16 millones de ciclos de reloj)
    SysTick->VAL = 0; //Reiniciamos el contador
    SysTick->CTRL &= ~(SYsTick_CTRL_TICKINT_Msk); //Deshabilitamos la interrupción
    SysTick->CTRL |= (SysTick_CTRL_CLKSOURCE_Msk); //Seleccionamos el reloj del procesador

    SysTick->CTRL &= ~(SysTick_CTRL_ENABLE_Msk); //Deshabilitamos el contador
    SysTick->CTRL |= SysTick_CTRL_ENABLE_Msk; //Habilitamos el contador ¿Por qué?
}